export interface ModelBudget { requests: number; concurrency: number; maxInputBytes: number; maxOutputBytes: number; inputBytes: number; outputBytes: number; timeoutMs: number }
export interface ImageBudget extends ModelBudget { maxImagesPerRequest: number; images: number; maxStorageBytes: number; storageBytes: number }
export interface ClassifierChoice { id: string; name: string; supported: boolean; unavailableReason?: string; price: object | null }
export interface ClassifierBinding { accountId: string; model: string; budget: ModelBudget; choice?: ClassifierChoice }
export interface ImageBinding { accountId: string; model: string; budget: ImageBudget; choice?: ClassifierChoice }
export interface ClassifierConfig { revision: number; classifier: ClassifierBinding | null; image?: ImageBinding | null }
export interface SessionImage { requestId: string; index: number; projectPath: string; sessionId: string; taskId: string; accountId: string; model: string; parentToolCallId: string; inputDigest: string; sha256: string; bytes: number; width: number; height: number; mimeType: string; createdAt: string }
export interface ModelRequest { requestId: string; parentToolCallId: string; kind?: "classifier" | "image"; status: "reserved" | "dispatched" | "unknown" | "not_sent" | "completed" | "failed"; reservation: { inputBytes: number; outputBytes: number; images?: number; storageBytes?: number }; result?: { answers?: Record<string, unknown>; responseId?: string | null }; storage?: { status: "saved" | "partial" | "failed" | "unknown" | "invalid"; artifacts: SessionImage[]; bytes: number; error?: string; rejected?: string[] }; priceSnapshot?: { value: object | null; source: string; at: string; currency: string; hardLimit: boolean }; usage: { status: string; tokens: { input: number; output: number } | null; coverage?: { input: number | null; output: number | null }; estimatedCost: number | null }; error?: string }
export interface ModelTask { taskId: string; sessionId: string | null; snapshot: ClassifierConfig; requests: ModelRequest[] }
export interface ModelLedger { protocol: 1; config: ClassifierConfig; tasks: ModelTask[] }
export interface ImageReference { entryId: string; artifact: SessionImage; shared: boolean; state: "available" | "unavailable"; error?: string; storageStatus?: string }
export interface SessionImagesView { sessionId: string; images: ImageReference[]; exportAvailable: boolean; space: { availableBytes: number | null; referencedBytes: number; cleanup: "EXPLICIT_ONLY" } }
export interface ImageExport { operationId: string; status: "prepared" | "dispatched" | "unknown" | "completed" | "failed" | "cancelled"; source: SessionImage; target: { path: string; exists: boolean; beforeSha256: string | null; beforeBytes: number | null }; error?: string; reconciled?: boolean; sha256?: string; bytes?: number }
